    title: "26일 본회의, 비쟁점 법안만 처리 — 용산공원특별법 두 번째 보류",
    description:
      "국회가 26일 본회의를 열어 법안 34건을 처리했습니다. 여야 합의로 올린 비쟁점 안건이 대부분이었지만, 공공기관 운영에 관한 법률 개정안(김병기 의원 등 166인)은 찬성 152·반대 74로 표가 갈렸고, 기후위기 대응을 위한 탄소중립·녹색성장 기본법 개정안(찬성 174·반대 15·기권 15)과 농어업회의소법 제정안(찬성 180·반대 10·기권 25)도 반대·기권이 함께 나왔습니다. 반면 최대 쟁점이던 용산공원 특별법 개정안은 이번에도 본회의에 오르지 못했습니다. 용산 캠프킴 부지의 공원녹지 기준을 완화해 주택 2,500여 가구를 공급할 수 있게 하는 내용으로, 지난 20일 본회의에서 유보된 데 이어 두 번째 보류입니다. 함께 부의돼 있던 도시재정비촉진법 개정안(공공정비 용적률 한시 완화)과 도시 및 주거환경정비법 개정안(인가 절차 병행으로 사업기간 단축)도 이날 상정되지 않아, 부동산 3법이 모두 정기국회로 넘어갔습니다. 민주당은 정부 공급대책의 후속 입법이라며 처리를 주장했지만, 국민의힘은 지난 4월 국토교통위원회에서 민주당이 이 법안을 일방 처리한 점을 들어 본회의 상정에 합의할 수 없다는 입장을 고수했습니다. 최수진 국민의힘 원내대변인은 '용산공원 조성 특별법 개정안은 협상 중인 안건에 올라가지 않았고 처리되지 않을 것'이라고 밝혔고, 야당은 일방 상정 시 필리버스터로 맞서겠다는 방침도 전달한 상태입니다. 민주당 천준호 원내수석부대표는 국토교통부 장관과 서울시장의 논의 내용을 반영해 다음 주에 처리하기로 의견을 모았다고 설명했습니다. 여야는 27~28일 각각 연찬회를 열어 후반기 정기국회 입법 전략을 논의합니다.",
