    id: "2026-08-13-climate-committee-carbon-neutrality",
    title: "기후특위, 탄소중립기본법 개정안 의결 (8/13) — 2040년 감축목표 69~80%, 헌재 결정 2년 만",
    description:
      '국회 기후위기특별위원회가 13일 전체회의를 열고 탄소중립기본법 개정안을 찬성 11, 반대 2, 기권 2로 의결해 본회의로 넘겼습니다. 2024년 8월 헌법재판소가 "2030년까지의 감축목표만 규정하고 2050년 탄소중립에 이르는 경로를 제시하지 않은 것은 미래세대에 과도한 부담을 떠넘긴다"며 헌법불합치 결정을 내린 지 약 2년 만입니다. 개정안은 2018년 배출량을 기준으로 2035년 53~61%, 2040년 69~80%, 2045년 84~90%의 국가 온실가스 감축목표를 법률에 명시하되, 구체적 수치는 이 범위 안에서 대통령령으로 정하도록 했습니다. 하나의 수치가 아닌 \'범위형\' 목표를 택한 것은 초기 감축을 강하게 하는 오목형 경로와 균등하게 줄이는 선형 경로를 두고 갈린 여야가 절충점을 찾은 결과입니다. 다만 기준선을 선형 경로로 잡으면서 환경단체들은 강하게 반발했습니다. 플랜1.5는 "헌재 기준과 공론화로 확인된 시민 요구에 명백히 배치된다"고 했고, 녹색연합은 "여야 합의를 명분으로 헌재 결정과 기본권 보호를 외면했다"고 비판했습니다. 반면 산업계는 목표치 자체가 달성 불가능한 수준이라는 입장이어서 양쪽에서 비판을 받는 모양새입니다. 반대표를 던진 정혜경·서왕진 의원과 기권한 이소영·조지연 의원도 감축 수준과 경로 설정을 문제 삼았습니다. 김정호 위원장은 "2026년 2월 28일 시한을 넘겼지만 이제라도 위헌 법률 개정 의무를 다하게 돼 다행"이라고 밝혔습니다. 기후특위는 이번 의결을 끝으로 8월 말 17개월간의 활동을 마무리합니다. 개정안은 8월 임시국회 본회의에서 처리될 전망이나, 여야가 의사일정에 합의하지 못해 본회의 날짜는 아직 확정되지 않았습니다.',
