    title: "민주 전대 김민석 2연승 (8/9) — 강원·TK 48.54%, 누적 1.48%p 차로 격차 확대",
    description:
      "더불어민주당 8·17 전당대회 순회경선 강원·대구·경북 결과가 9일 저녁 발표되면서 김민석 후보가 전날 제주·인천에 이어 2연승을 거뒀습니다. 김 후보는 세 지역 합산 1만 8,977표(48.54%)를 얻어 정청래 후보(1만 7,355표·44.40%)를 1,622표(4.14%포인트) 차로 앞섰고, 송영길 후보는 2,760표(7.06%)에 그쳤습니다. 이로써 누적 득표율은 김민석 46.01%, 정청래 44.53%, 송영길 9.47%가 되어 두 후보의 격차가 전날 0.86%포인트에서 1.48%포인트로 벌어졌습니다. 다만 이는 경남과 대구·경북에 부여되는 지역별 가중치를 반영하지 않은 단순 합산입니다. 지역별로는 승부가 갈렸습니다. 강원에서 김 후보가 9,568표(50.30%)로 정 후보(7,978표·41.94%)를 8.36%포인트 차로 눌렀고 경북에서도 4,948표(47.37%)로 정 후보(4,774표·45.71%)를 근소하게 앞섰지만, 대구에서는 정 후보가 4,603표(47.82%)를 얻어 김 후보(4,461표·46.35%)를 142표 차로 이겼습니다. 강원에서 벌어진 1,590표 차이가 전체 승패를 갈랐습니다. 순회경선 전적은 김 후보가 2승 1패, 정 후보가 1승 2패입니다. 이번 권역은 권리당원 비중이 크지 않아 판세를 크게 흔들지는 않을 것으로 보입니다. 승부처는 권리당원의 33%가 몰린 15일 호남(전남·광주·전북)과 38%가 걸린 16일 수도권(경기·서울)입니다. 최고위원 경선에서는 최민희 후보가 누적 20.28%로 선두이고 박선원(16.74%), 한민수(14.39%), 서미화(14.24%), 김용(12.65%) 후보가 뒤를 잇고 있습니다. 최종 승자는 17일 대전에서 열리는 전당대회에서 대의원·권리당원 투표 70%와 국민 여론조사 30%를 합산해 가려집니다.",
