    title: "국민의힘 윤리위, 징계 절차 개시 (8/7) — 서범수·진종오 · 윤리위원 2명 사퇴로 내홍 격화",
    description:
      "국민의힘 중앙윤리위원회가 7일 여의도 중앙당사에서 회의를 열고 이른바 '돌려차기 실언'으로 논란이 된 서범수·진종오 의원에 대한 징계 절차 개시를 의결했습니다. 두 의원은 지난 4일 무소속 한동훈 의원이 주최한 검찰 보완수사권 폐지 관련 간담회에서 부산 돌려차기 사건 피해자가 입장하기 전 부적절한 발언을 주고받아 논란이 됐고, 전날 최고위원회의에서 엄중 조치 필요성이 제기된 데 이은 후속 절차입니다. 다만 절차 개시 과정에서 당내 갈등이 오히려 커졌습니다. 두 의원이 이미 피해자에게 사과했고 피해자도 선처를 요청한 상태인 데다, 정의화 전 국회의장이 공개 사과와 화해가 이뤄졌다며 선처를 촉구하는 탄원서를 냈고 정점식 원내대표도 징계에 거리를 두며 신중론을 폈지만 윤리위는 개시를 강행했습니다. 이 과정에서 윤리위원 2명이 독립성 훼손을 이유로 사퇴했습니다. 윤리위는 같은 날 지난달 27일 징계 절차를 개시한 조경태·권영진 의원에 대해서도 사실관계 확인 질의서를 발송하기로 했습니다. 조 의원은 박덕흠 국회부의장 후보 반대를 부탁한 건, 권 의원은 정점식 원내대표와의 물리적 충돌이 제소 사유입니다. 비당권파에서는 당권파 인사들의 유사한 언행에는 아무 조치가 없으면서 자신들만 징계 대상이 된다며 형평성을 문제 삼고 있어, 징계 국면이 계파 갈등으로 번지는 양상입니다.",
