    title: '레버리지 ETF 국정조사 공방 (8/5) — 국민의힘 "증시 도박판" vs 민주당 "정치공세"',
    description:
      "단일종목 레버리지 상장지수펀드(ETF) 도입을 둘러싼 여야 공방이 8월 임시국회의 새 쟁점으로 떠올랐습니다. 국민의힘은 지난 1일 레버리지 ETF 도입 과정과 최근 증시 급변동에 대한 국정조사를 공식 추진하겠다고 밝혔습니다. 박성훈 수석대변인은 정부가 '서학개미를 국장으로 돌아오게 하겠다'며 위험한 상품을 허용했으나 결과는 처참했다고 주장했고, 김용범 대통령실 정책실장의 경질도 요구했습니다. 정점식 원내대표는 국정조사 대상으로 레버리지 ETF 도입 과정과 여파, 정부의 주식시장 과열 조장 여부, 국민연금 등 연기금의 국내 주식 투자 동향, 금융감독 당국의 역할 적정성 등을 제시했습니다. 민주당은 제도 보완 필요성은 인정하면서도 국정조사와 특검 요구는 선을 그었습니다. 박지원 최고위원은 정부 당국자가 상품 도입 과정에서 위험성과 투자자 보호장치를 충분히 살피지 못한 점을 인정하고 사과했다며 책임을 인정하면서도, 정책 판단의 잘못과 선거 목적의 범죄행위는 전혀 다르다고 강조했습니다. 박지혜 대변인은 국정조사·특검 언급을 지방선거와 결부된 정치공세로 규정하고, 증시 변동에는 AI 투자 수익성 우려와 중국발 반도체 경쟁, 유가 불안, 미국 금리 상승 우려 등 대외 요인이 겹쳤다고 설명했습니다. 정부는 7월 30일부터 기본예탁금을 1,000만원에서 3,000만원으로 올렸고, 개인별 투자 한도 설정과 모의거래 의무화 등 추가 규제를 검토 중입니다.",
