    title: "민주 전대 누적 0.99%p 초접전 (8/4) — 당권주자 호남 총출동, 최대 승부처 11~14일 투표",
    description:
      "더불어민주당 8·17 전당대회 당대표 순회경선이 1주 차를 마친 가운데 누적 득표율 격차가 1%포인트 이내로 좁혀졌습니다. 8월 1일 발표된 충청권에서는 김민석 후보가 45.06%로 정청래 후보(44.61%)를 0.45%포인트 차로 눌렀고, 2일 부산·울산·경남에서는 정청래 후보가 46.65%로 김민석 후보(43.85%)를 2.8%포인트 차로 제치며 1승씩을 주고받았습니다. 두 지역을 합산한 누적 득표율은 정청래 후보 45.51%, 김민석 후보 44.52%로 격차가 0.99%포인트에 불과합니다. 다만 이는 전략지역인 경남에 부여된 5% 가중치가 반영되지 않은 수치입니다. 이처럼 초박빙 구도가 이어지면서 전체 권리당원의 약 33%가 몰려 있는 호남이 최대 승부처로 떠올랐습니다. 당대표 후보 3인은 4일 일제히 호남을 찾아 표심 공략에 나섰습니다. 정청래 후보는 전남광주 말바우시장에서 시민들과 인사한 뒤 지체장애인협회 간담회를 갖고 소방공무원, 개인택시조합원들을 만났습니다. 송영길 후보는 전남 화순 너릿재 5월의 길을 찾은 뒤 화순군의회와 나주에서 '시민 공감 토크'를 열고 한국전력공사 본사를 방문했습니다. 호남 권리당원 투표는 11일부터 14일까지 진행되며 결과는 15일 발표됩니다. 이후 16일 서울·경기(권리당원 약 38%) 경선이 남아 있어, 사실상 호남과 수도권에서 승부가 갈릴 전망입니다.",
