    title: "8월 임시국회 개회 (8/3) — 패스트트랙 단축법 표결만 남아 · 첫 본회의는 13일 전후 전망",
    description:
      "8월 임시국회가 지난 2일 회기를 시작하며 문을 열었습니다. 국회법상 8월 임시회는 16일 자동 소집되지만, 이번에는 국민의힘이 먼저 소집을 요구해 2일부터 회기가 개시됐습니다. 다만 실제 본회의 가동은 더불어민주당 전당대회(8월 17일) 일정을 감안해 이르면 13일쯤으로 관측됩니다. 첫 본회의의 최우선 안건은 패스트트랙 심사 기간을 최장 330일에서 90일로 줄이는 국회법 개정안입니다. 지난달 31일 본회의에 상정된 뒤 국민의힘이 필리버스터로 맞섰지만 7월 임시국회 회기 종료와 함께 토론이 자동 종결돼, 이제 표결 절차만 남은 상태입니다. 민주당은 여기에 더해 필리버스터 종결 요건 완화, 의결정족수 미달 시 의장의 회의 중지 권한 부여, 상임위원장의 의도적 의사 지연 시 강제 교체 등 국회법 추가 개정도 추진하고 있어 국민의힘은 총력 저지를 예고했습니다. 여야가 합의 처리한 선관위 특검법도 후속 절차에서 다시 부딪히고 있습니다. 여야 각 3명씩 참여하는 국민추천위원회 구성·운영 방식이 정해지지 않았고, 수사 범위를 두고도 민주당은 6·3 지방선거로 한정해야 한다는 입장인 반면 국민의힘은 과거 선거까지 확대할 수 있다고 맞서고 있습니다. 국민의힘은 별도로 주식시장 급변동에 대한 국정조사도 제안한 상태입니다.",
