      '검사의 직접수사권과 보완수사권을 전면 폐지하는 형사소송법 개정안이 31일 국회 본회의를 통과했습니다. 더불어민주당 등 범여권은 전날부터 이어진 국민의힘의 필리버스터를 24시간 경과 후 종결동의 표결로 중단시키고 곧바로 표결에 들어갔고, 개정안은 재석 178명 중 찬성 175명, 반대 2명, 기권 1명으로 가결됐습니다. 반대는 더불어민주당 곽상언·개혁신당 이주영 의원, 기권은 민주당 이소영 의원으로 범여권 내부에서도 이탈표가 나왔습니다. 국민의힘은 표결에 불참했습니다. 개정안은 수사 주체를 경찰로 일원화하고 검사에게는 보완수사요구권만 남기는 내용으로, 1948년 검찰청법 제정 이후 78년 만에 검찰의 수사권이 사라지는 형사사법 체계의 대전환입니다. 올해 10월 2일 시행되는 공소청법·중대범죄수사청법에 맞춘 후속 입법으로, 여당은 "수사·기소 분리를 완성하는 역사적 전환점"이라고 평가한 반면 국민의힘은 "수사 현장의 혼란을 부를 희대의 악법"이라며 반발했습니다. 표결 직후 패스트트랙 심사 기간을 330일에서 90일로 줄이는 국회법 개정안이 상정되자 국민의힘은 김미애 의원을 첫 주자로 두 번째 필리버스터에 돌입했습니다. 이 필리버스터는 이날 자정 7월 임시국회 회기 종료와 함께 자동 종결되며, 국회법 개정안은 8월 임시국회 첫 본회의에서 표결됩니다.',
