    description:
      "한성숙 국무총리 후보자 인사청문 경과보고서가 6월 30일 국회 인사청문특별위원회에서 더불어민주당 주도로 채택됐습니다. 국민의힘은 안건 상정에 반발하며 회의와 보고서 채택에 모두 불참했고, 보고서에는 '적격' 다수 의견과 함께 '부적격' 의견이 병기됐습니다. 민주당은 같은 날 오후 본회의를 열어 한성숙 임명동의안을 표결에 부치고, 후반기 원 구성도 18개 상임위원장을 민주당 주도로 단독 선출해 마무리하는 수순에 들어갔습니다. 국무총리 임명동의안은 재적 과반 출석에 출석 과반 찬성으로 가결되는데, 민주당이 단독 과반을 확보하고 있어 인준에는 큰 변수가 없을 것으로 관측됩니다. 상임위원장은 민주당 몫 11곳을 먼저 선출하는 방안이 거론되며, 법제사법위원회에 더해 정무·기획재정·국토교통·산업통상자원중소벤처 등 핵심 경제 상임위를 민주당이 가져가는 구도가 유력합니다. 국민의힘은 '여당의 독주'라며 강하게 반발했습니다. 이로써 6월 19일 1차 시한 이후 법사위원장 배분을 둘러싸고 공전하던 22대 후반기 원 구성이 여당 단독 처리로 매듭지어지는 국면을 맞았습니다.",
