    title:
      "원 구성 협상 데드라인 '6월 말'로 재설정 — 한병도 '21대 법사위서 노란봉투법 등 폐기' vs 국힘 '권력 사유화 막아야', 한성숙 청문회 D-5",
    description:
      "22대 후반기 국회 원 구성 협상이 1차 시한(6월 19일)을 넘긴 뒤 6월 20일에도 법제사법위원장을 둘러싼 여야 대치가 풀리지 않았습니다. 여야는 협상 데드라인을 일단 6월 말로 다시 늦추고 논의를 이어가기로 했습니다. 더불어민주당 한병도 원내대표는 '노란봉투법·간호법·방송법·양곡관리법 등 민생 필수 법안들이 21대 국회 법사위에 묶여 있다가 폐기됐다'며, 이재명 정부 국정과제의 안정적 추진을 위해 법사위원장을 사수해야 한다는 입장을 거듭 밝혔습니다. 반면 국민의힘 최보윤 수석대변인은 야당이 법사위원장을 맡는 것이 '권력의 사유화를 막으라는 6·3 지방선거의 준엄한 민심을 따르는 길'이라며, 거대 여당 견제를 위해 법사위원장은 제2당 몫이어야 한다고 맞섰습니다. 협상이 계속 공전할 경우 원내 과반인 민주당이 표결로 18개 상임위원장을 단독 선출하는 방안도 거론됩니다. 민주당은 2024년 22대 전반기에도 11개 상임위원장을 단독 처리한 전례가 있으나, '독식' 논란 부담 탓에 강행 여부는 유동적입니다. 한편 한성숙 국무총리 후보자 인사청문회(6/25~26)가 닷새 앞으로 다가오면서, 자료 제출 요구 기한인 6월 22일 오후 4시를 기점으로 인사청문 정국도 본격화됩니다. 인사청문특별위원회는 위원장 백혜련(민주)·간사 김한규(민주)·강승규(국힘) 등 13명으로 구성됐고, 국민의힘 측 위원으로 3선 김희정 의원 등이 합류했습니다. 결국 원 구성·국정조사·총리 인사청문이 6월 하순에 한꺼번에 맞물려 돌아가게 됐습니다.",
