      "22대 후반기 국회 원 구성 협상이 1차 목표 시한이던 6월 19일을 끝내 넘겼습니다. 한병도 더불어민주당 원내대표와 정점식 국민의힘 원내대표는 이날 '2+2' 회동을 갖고 18개 상임위원장 배분을 논의했으나 합의에 이르지 못했습니다. 한 원내대표는 회동 후 기자들에게 '법사위가 안 되니까 진전이 안 된다'며 협상 실패를 알렸습니다. 최대 쟁점은 법제사법위원장 배분입니다. 민주당은 법사위 권한을 국민의힘에 넘기면 이재명 정부의 개혁 입법이 지연될 수 있다며 사수 입장을, 국민의힘은 국회의장을 원내 1당이 맡은 만큼 견제와 균형 차원에서 법사위원장은 제2당이 맡아야 한다는 입장을 굽히지 않았습니다. 여야는 일단 협상 시한을 다음 주까지로 늦추고 논의를 이어가기로 했으나, 법사위원장 쟁점이 그대로여서 타결 전망은 불투명합니다. 협상이 계속 공전할 경우 원내 과반인 민주당이 상임위원장을 단독 처리하는 방안도 거론되지만, '독식' 논란 부담이 있어 실제 강행 여부는 미지수입니다. 한편 전날(6/18) 본회의에서 6·3 투표용지 부족 사태 국정조사 계획서가 의결돼 국조특위(위원장 윤상현)가 가동에 들어갔고, 한성숙 국무총리 후보자 인사청문회(6/25~26)도 다음 주로 다가와, 원 구성·국정조사·인사청문이 6월 하순에 한꺼번에 맞물리게 됐습니다.",
