      "22대 후반기 원 구성 협상 시한(6월 19일)을 일주일 앞둔 6월 12일, 여야 원내대표가 법제사법위원장을 놓고 정면으로 충돌했습니다. 한병도 더불어민주당 원내대표는 광주에서 열린 현장최고위원회의에서 '법사위원장 자리는 협상의 대상이 아니다'라고 못 박았습니다. 전반기 국민의힘이 맡았던 정무위·외교통일위·국방위는 입법이 더뎠다며, 국민의힘이 법사위원장까지 맡으면 '국정과제와 민생 현안을 발목 잡을 것이 자명하다'고 했습니다. 같은 날 정점식 국민의힘 원내대표는 취임 후 첫 기자간담회에서 '법사위원장은 야당 몫으로 돌려놔야 한다'고 맞받았습니다. 과거 정청래·추미애 법사위원장 체제의 '입법 독주를 끝내고 견제와 균형의 국회를 되살려야 한다'는 논리로, 나아가 기획재정위·정무위·산업통상자원중소벤처기업위·국토교통위 등 핵심 경제 상임위도 야당이 맡아야 한다며 요구 수위를 높였습니다. 법사위는 모든 법안이 본회의에 오르기 전 거치는 관문이어서 원 구성 최대 쟁점입니다. 6·3 투표용지 부족 사태 국정조사를 둘러싼 이견도 그대로입니다. 특위 구성을 놓고 민주당은 '의석수 비율 배분·위원장 여당', 국민의힘은 '여야 동수·위원장 야당'으로 맞서고, 특검도 민주당은 '국조·합동수사본부 수사 결과를 본 뒤 검토', 국민의힘은 '국조와 특검 투트랙 동시 추진'으로 갈립니다. 민주당은 6월 18일 본회의에서 국정조사 계획서를 채택해 국조특위를 '개문발차'하겠다는 방침이어서, 다음 주가 후반기 국회 협상의 1차 분수령이 될 전망입니다.",
