    title:
      "여야 신임 원내대표 첫 회동 — 선관위 국조 계획서 내주 처리 합의, 원 구성은 '법사위' 줄다리기 시작",
    description:
      "22대 후반기 여야 원내 사령탑이 6월 11일 처음 마주 앉았습니다. 취임 첫날인 정점식 국민의힘 원내대표는 한병도 더불어민주당 원내대표를 비롯해 조정식 국회의장, 홍익표 대통령실 정무수석과 릴레이 회동을 갖고 후반기 국회 운영 협상에 시동을 걸었습니다. 양당 원내대표는 조정식 의장 주재 회동에서 6·3 투표용지 부족 사태 국정조사 계획서를 다음 주 본회의에서 처리하기로 의견을 모았고, 이날 본회의에는 여야가 각각 당론 제출한 국정조사 요구서 2건이 보고됐습니다. 전반기에 처리하지 못한 비쟁점 법안 87건 중 여야 합의 50건을 신속 처리하기 위해 원내대표가 월 1회 이상 만나는 민생법안협의체(가칭) 구성에도 합의했습니다. 그러나 원 구성을 놓고는 곧바로 신경전이 시작됐습니다. 한병도 원내대표가 '여야가 머리를 맞대 날을 새워서라도 빨리 원 구성을 하자'고 하자, 정점식 원내대표는 '거대 의석의 민주당이 많이 양보해 주시면 하루 이틀 만에도 합의할 수 있다'고 받았고, 이어 '법제사법위원장을 제2당 몫으로 내놓는 것이 6·3 지방선거 민심에 부응하는 첫걸음'이라며 법사위원장 양보를 공개 요구했습니다. 민주당은 검찰개혁 후속 입법 등을 이유로 법사위 사수 입장이어서 강대강 대치가 예상됩니다. 국정조사 역시 큰 틀의 공감대와 달리 특위 구성 방식(민주 의석비율 배분 vs 국힘 여야 동수)과 조사 대상(국힘은 출구조사 발표 경위·경찰 진압·선거 효력까지 포함 요구, 민주는 '부정선거 끼워넣기'라고 반박)을 놓고 이견이 남아 있습니다.",
