    title:
      "6·3 지방선거 본투표일 — 낮 12시 투표율 19.0%(역대 지선 최고 추세), 오후 6시 출구조사·개표 시작",
    description:
      "제9회 전국동시지방선거와 국회의원 재보궐선거 본투표가 6월 3일 오전 6시 전국 14,288개 투표소에서 일제히 시작됐습니다. 중앙선거관리위원회에 따르면 누적 투표율은 오전 8시 4.5%, 9시 7.4%, 10시 11.0%, 11시 15.0%를 거쳐 낮 12시 현재 19.0%를 기록, 직전 2022년 제8회 지방선거 동시간대(15.0%)보다 4.0%포인트 높아 역대 지방선거 최고치 추세를 이어가고 있습니다. 사전투표 23.51%(역대 최고)에 본투표 열기가 더해진 양상입니다. 다만 지역별로는 사전투표와 뚜렷한 온도 차가 나타나, 낮 12시 기준 대구(23.7%)·경북(21.7%)·강원(21.6%)·경남(21.2%) 등 영남권이 높고 광주(13.1%)·전북(14.8%)·전남(14.9%) 등 호남권이 낮아 사전투표(호남 강세) 때와 역전된 흐름을 보였습니다. 투표는 오후 6시 마감되며, 같은 시각 지상파 방송 3사(KBS·MBC·SBS)가 전국 595개 투표소에서 약 10만 명을 대상으로 진행한 공동 출구조사 결과가 발표됩니다. 사전투표자(전체의 40%대) 표심은 5/30~6/2 별도 전화조사(2만8,500명)로 보정됩니다. 방송사 예측 당선인·득표율 보도는 오후 6시 15분부터, 실제 개표는 오후 6시 20분께 시작돼 당선 윤곽은 자정 무렵, 박빙 격전지는 새벽 3~4시께 가려질 전망입니다. 함께 치러지는 재보궐선거 14곳 중 부산 북구갑·경기 평택을 두 곳은 별도 출구조사 대상에 포함됐습니다.",
