    description:
      '6·3 전국동시지방선거를 이틀 앞둔 6월 1일, 여야는 마지막 평일을 맞아 부동층을 투표장으로 끌어내기 위한 무박 총력전에 돌입했습니다. 더불어민주당 정청래 총괄상임선거대책위원장은 오전 9시 30분 충남 천안에서 박수현 충남지사 후보 중앙선대위 회의를 시작으로 충북 괴산(신용한 지사·이차영 군수 후보)→경북 안동(오중기 지사·이삼걸 시장 후보)→울산 남구(김상욱 시장 후보)로 이어지는 충청·영남 종단 유세에 나서며 "이번 선거는 이재명 대통령에게 힘을 실어드리는 선거"라고 기호 1번 지지를 호소했습니다. 국민의힘 장동혁 상임선거대책위원장은 오전 11시 제주 동문재래시장→서귀포 매일올레시장을 돈 뒤 오후 울산 신정시장으로 이동해 "투표로 이재명의 폭주를 멈춰 세우자"며 정권 견제론으로 보수 결집을 촉구했습니다. 개혁신당 이준석 총괄선대위원장은 수도권 승부처인 경기 화성 동탄(카림애비뉴·센트럴파크)에 화력을 집중했습니다. 막판 변수는 전·현직 대통령의 광폭 행보로, 이명박 전 대통령은 5월 31일 부산 해운대시장에서 박형준 부산시장 후보를, 박근혜 전 대통령은 같은 날 대구 서문시장에서 추경호 대구시장 후보를 지원하며 보수 텃밭 결집에 나섰습니다. 이재명 대통령은 5월 30일 SNS에 "투표 포기는 중립이 아니라 내 삶과 공동체를 해치는 그들을 편드는 것"이라며 참여를 독려했습니다. 여론조사 공표가 금지된 깜깜이 국면에서 사전투표 23.51%(역대 지선 최고)의 열기가 본투표로 이어질지가 6월 3일 최종 승부를 가를 전망입니다.',
